let state=load(),view='dashboard',selectedFigure=null,selectedTag=null,selectedMonster=null,monsterTab='link',selectedStoryEnemy=null,soulTab='records',selectedSoul=null,dirty=false,organizeTab='figures',auditFilter='all',diffDomain='figures',compareState=upgradeState(clone(SEED)),compareLabel='初期スナップショット',undoStack=[];
