function getAvailableMonsterTab(link,preferred){const wants=preferred||monsterTab||'link';if(!link)return 'link';if(wants==='story'&&link.storyPresent)return 'story';if(wants==='monsters'&&link.monstersPresent)return 'monsters';if(wants==='compare'&&link.storyPresent&&link.monstersPresent)return 'compare';if(wants==='link')return 'link';if(link.storyPresent)return 'story';if(link.monstersPresent)return 'monsters';return 'link'}

function upgradeState(src){const x=src&&typeof src==='object'?src:clone(SEED);x.meta={...(x.meta||{}),appVersion:'0.3.1',schemaVersion:3,safeMode:true,history:Array.isArray(x.meta?.history)?x.meta.history:[]};x.settings={githubRawBase:'',imageExtension:'png',...(x.settings||{})};x.sync={imports:[],imageAudit:null,...(x.sync||{})};x.sync.imports=Array.isArray(x.sync.imports)?x.sync.imports:[];x.figures=Array.isArray(x.figures)?x.figures:[];x.tags=Array.isArray(x.tags)?x.tags:[];x.story=x.story||clone(SEED.story);x.monsters=x.monsters||clone(SEED.monsters);x.monsters.system=x.monsters.system||clone(DEFAULT_MM_SYSTEM);x.monsterLinks=Array.isArray(x.monsterLinks)?x.monsterLinks:clone(SEED.monsterLinks||[]);x.figures.forEach((f,i)=>{f.displayOrder=Number(f.displayOrder)||i+1;f.image=f.image||{folder:'fig',file:'',path:''};f.canonicalTags=Array.isArray(f.canonicalTags)?f.canonicalTags:[];f.story=f.story||{present:false,tags:[]};f.piece=f.piece||{present:false};});x.tags.forEach((t,i)=>{t.displayOrder=Number(t.displayOrder)||i+1;t.category=t.category||'その他';t.notes=t.notes||'';});return x}
function load(){for(const key of [STORAGE,...LEGACY_STORAGES]){try{const raw=localStorage.getItem(key);if(!raw)continue;const x=upgradeState(JSON.parse(raw));if(key!==STORAGE)localStorage.setItem(STORAGE,JSON.stringify(x));return x}catch(e){}}return upgradeState(clone(SEED))}
function pushHistory(msg){state.meta.history=Array.isArray(state.meta.history)?state.meta.history:[];state.meta.history.unshift({at:new Date().toISOString(),message:msg||'データを更新'});state.meta.history=state.meta.history.slice(0,120)}
function persist(msg,opts={}){if(!opts.noUndo&&lastCommitted){undoStack.push(clone(lastCommitted));if(undoStack.length>6)undoStack.shift();try{localStorage.setItem(RESTORE_KEY,JSON.stringify(lastCommitted))}catch(e){}}state.meta.updatedAt=new Date().toISOString();if(!opts.skipHistory)pushHistory(msg||'データを更新');localStorage.setItem(STORAGE,JSON.stringify(state));lastCommitted=clone(state);dirty=true;if(msg)toast(msg);updateTitle();updateUndoButton();}
function updateUndoButton(){const b=$('#undoBtn');if(b)b.disabled=!undoStack.length}
function undoLast(){if(!undoStack.length)return toast('戻せる変更がありません');const prev=undoStack.pop();state=upgradeState(prev);pushHistory('UNDO: 直前の変更を取り消し');state.meta.updatedAt=new Date().toISOString();localStorage.setItem(STORAGE,JSON.stringify(state));lastCommitted=clone(state);dirty=true;render();updateUndoButton();toast('直前の変更を取り消しました')}
function showHistory(){const rows=(state.meta.history||[]).slice(0,80);modal(`<h2>変更履歴</h2><div class="notice good">履歴は管理アプリ内の操作記録です。UNDOはこのブラウザセッション中の直近6回まで戻せます。</div><div class="history-list">${rows.length?rows.map(h=>`<div class="history-row"><b>${esc(new Date(h.at).toLocaleString('ja-JP'))}</b><span>${esc(h.message)}</span></div>`).join(''):'<div class="empty">履歴はまだありません</div>'}</div><div class="modal-actions"><button class="ghost" id="historyExport">履歴JSON</button><button class="ghost" id="historyClose">閉じる</button></div>`);$('#historyClose').onclick=closeModal;$('#historyExport').onclick=()=>download('mob-master-history.json',{generatedAt:new Date().toISOString(),history:state.meta.history||[]})}

function updateTitle(){document.title=(dirty?'● ':'')+'MOB MASTER MANAGER v0.3.0'}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),1800)}
function modal(html){$('#modalCard').innerHTML=html;$('#modal').hidden=false}
function closeModal(){$('#modal').hidden=true}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
function imageUrl(path){const base=(state.settings.githubRawBase||'').trim().replace(/\/$/,'');return base?base+'/'+String(path||'').replace(/^\//,''):''}
function img(path,name=''){const u=imageUrl(path);return `<div class="thumb">${u?`<img src="${esc(u)}" alt="${esc(name)}" onerror="this.replaceWith(document.createTextNode('IMG'))">`:'IMG'}</div>`}
function download(name,data,type='application/json'){const text=typeof data==='string'?data:JSON.stringify(data,null,2);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
function pageHead(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div><div class="page-actions">${actions}</div></div>`}
function tagName(mid){return state.tags.find(t=>t.masterId===mid)?.name||mid}
function currentTag(id){return state.tags.find(t=>t.currentId===String(id).padStart(2,'0'))}
function normalizeOrders(list){list.sort((a,b)=>(a.displayOrder||99999)-(b.displayOrder||99999));list.forEach((x,i)=>x.displayOrder=i+1)}
function summary(){
 const sf=state.figures.filter(f=>f.story.present).length,pf=state.figures.filter(f=>f.piece.present).length;
 const storyNames=new Set(state.story.enemies.map(e=>e.name)), monNames=new Set(state.monsters.monsters.map(e=>e.name));
 const tagDiff=state.figures.filter(f=>f.story.present&&f.piece.present&&JSON.stringify([...(f.story.tags||[])].sort())!==JSON.stringify([...(f.piece.tags||[])].sort())).length;
 return {sf,pf,total:state.figures.length,tags:state.tags.length,se:state.story.enemies.length,mm:state.monsters.monsters.length,storyOnly:[...storyNames].filter(x=>!monNames.has(x)).length,monOnly:[...monNames].filter(x=>!storyNames.has(x)).length,tagDiff,missingPiece:state.figures.filter(f=>f.story.present&&!f.piece.present).length};
}
function render(){
 $$('#mainnav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
 const r={dashboard:renderDashboard,sync:renderSync,figures:renderFigures,organize:renderOrganize,tags:renderTags,monsters:renderMonsters,soul:renderSoul,diff:renderDiff,audit:renderAudit,export:renderExport}[view]||renderDashboard;r();updateUndoButton();
}
