$('#settingsBtn').onclick=showSettings;updateUndoButton();
function showSettings(){modal(`<h2>設定</h2><div class="notice good">ゲーム本体への直接書き込みは常にOFFです。v0.1 / v0.2の保存データはv0.3へ自動引継ぎします。画像はGitHub Raw URLを使います。</div><div class="form-grid section"><div class="field full"><label>GitHub Raw Base URL</label><input id="setGithub" value="${esc(state.settings.githubRawBase||'')}" placeholder="https://raw.githubusercontent.com/.../main"></div><div class="field"><label>標準画像拡張子</label><input id="setExt" value="${esc(state.settings.imageExtension||'png')}"></div></div><div class="modal-actions"><button class="ghost" id="importBtn">BACKUP読込</button><button class="danger" id="resetBtn">初期スナップショットへ戻す</button><button class="ghost" id="closeBtn">閉じる</button><button class="primary" id="saveSettings">保存</button></div>`);
 $('#closeBtn').onclick=closeModal;$('#importBtn').onclick=()=>$('#importBackupFile').click();
 $('#saveSettings').onclick=()=>{state.settings.githubRawBase=$('#setGithub').value.trim();state.settings.imageExtension=$('#setExt').value.trim()||'png';persist('設定を保存しました');closeModal();render()};
 $('#resetBtn').onclick=()=>{modal(`<h2>初期状態へ戻しますか？</h2><div class="notice">管理アプリ内の編集内容だけを初期化します。ゲーム本体には影響しません。必要なら先にBACKUPしてください。</div><div class="modal-actions"><button class="ghost" id="cancelReset">キャンセル</button><button class="danger" id="doReset">初期化</button></div>`);$('#cancelReset').onclick=closeModal;$('#doReset').onclick=()=>{state=upgradeState(clone(SEED));localStorage.removeItem(STORAGE);LEGACY_STORAGES.forEach(k=>localStorage.removeItem(k));localStorage.removeItem(RESTORE_KEY);localStorage.removeItem(MANUAL_RESTORE_KEY);lastCommitted=clone(state);undoStack=[];dirty=false;closeModal();render();toast('初期スナップショットへ戻しました')}}
}
$('#importBackupFile').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{const x=JSON.parse(await f.text());if(!x.figures||!x.tags||!x.story||!x.monsters)throw new Error('形式が違います');state=upgradeState(x);lastCommitted=clone(state);persist('BACKUPを読み込みました',{noUndo:true});closeModal();render()}catch(err){toast('読込失敗: '+err.message)}});
