function renderDashboard(){const s=summary();
 $('#view').innerHTML=pageHead('MOB MASTER','3作品のデータを「壊さずに整理する」ための独立マスター管理アプリ',`<button class="primary" data-go="figures">フィギュア管理</button>`)+`
 <div class="stats-grid grid"><div class="stat"><small>MASTER FIGURES</small><strong>${s.total}</strong><em>統合件数</em></div><div class="stat"><small>STORY FIGURES</small><strong>${s.sf}</strong><em>現スナップショット</em></div><div class="stat"><small>PIECE FIGURES</small><strong>${s.pf}</strong><em>現スナップショット</em></div><div class="stat"><small>TAGS</small><strong>${s.tags}</strong><em>統合タグ</em></div><div class="stat"><small>STORY ENEMIES</small><strong>${s.se}</strong><em>遭遇データ</em></div><div class="stat"><small>MONSTERS</small><strong>${s.mm}</strong><em>育成モンスター</em></div></div>
 <div class="quick-grid grid"><button class="quick-card primary-card" data-go="sync"><b>SYNC CENTER</b><span>ZIP読込・3作品の更新状況・画像監査</span></button><button class="quick-card" data-go="organize"><b>ORGANIZE</b><span>並び替え・一括編集・再編シミュレーション</span></button><button class="quick-card" data-go="audit"><b>SAFETY CHECK</b><span>重複ID・参照切れを検査</span></button></div><div class="dashboard-grid grid"><section class="card"><h2>SYNC STATUS</h2><div class="sync-row"><b>MOB STORY</b><div class="progress"><i style="width:100%"></i></div><span class="status-good">SNAPSHOT</span></div><div class="sync-row"><b>MOB PIECE BATTLE</b><div class="progress"><i style="width:${Math.round(s.pf/s.sf*100)}%"></i></div><span class="status-warn">${s.missingPiece} 未反映候補</span></div><div class="sync-row"><b>MOB MONSTERS</b><div class="progress"><i style="width:${Math.round(s.mm/new Set(state.story.enemies.map(e=>e.name)).size*100)}%"></i></div><span class="status-warn">仕様別管理</span></div><div class="notice good" style="margin-top:12px">内部IDと表示順を分離しています。並べ替えやタグ整理をしても、元ゲームのIDを勝手に書き換えません。</div></section>
 <section class="card"><h2>CHECK</h2><div class="issue-list"><div class="issue">STORY / PIECE のタグ構成差：<b>${s.tagDiff}</b> 件</div><div class="issue">STORYにありPIECEに無いフィギュア：<b>${s.missingPiece}</b> 件</div><div class="issue">STORY名のみ：<b>${s.storyOnly}</b> / MONSTERS名のみ：<b>${s.monOnly}</b></div><div class="issue">ソウルレコード：<b>${state.monsters.records.length}</b> / スキル：<b>${Object.keys(state.monsters.skills).length}</b></div></div></section></div>`;
 $$('[data-go]').forEach(b=>b.onclick=()=>{view=b.dataset.go;render()});
}
function filteredFigures(){const q=($('#figureSearch')?.value||'').trim().toLowerCase(),game=$('#figureGame')?.value||'all',rar=$('#figureRarity')?.value||'all';return [...state.figures].sort((a,b)=>a.displayOrder-b.displayOrder).filter(f=>(!q||`${f.name} ${f.image.path} ${f.story.sourceId||''} ${f.piece.sourceId||''}`.toLowerCase().includes(q))&&(game==='all'||game==='story'&&f.story.present||game==='piece'&&f.piece.present||game==='storyOnly'&&f.story.present&&!f.piece.present)&&(rar==='all'||f.rarity===rar))}
