function createSoulRecord(){const n=state.monsters.records.length+1,id='SR-'+String(n).padStart(3,'0'),o={id,name:'新SOUL RECORD',category:'GENERAL',origin:'共通',secondaryOrigin:'',theme:'',attribute:'無',growth:'',inheritLevel:30,masterLevel:70,notes:'',milestones:[]};state.monsters.records.push(o);selectedSoul=id;persist('SOUL RECORD「'+id+'」を作成');renderSoul();selectedSoul=id;setTimeout(()=>renderSoulDetail(),0)}
function saveSoulRecordForm(x){let adv={};try{adv=JSON.parse($('#soulJson').value||'{}')}catch(e){return toast('Advanced JSONを確認してください')}const rows=$$('[data-ms-row]').map(r=>({level:Number($('[data-ms="level"]',r).value)||1,type:$('[data-ms="type"]',r).value.trim(),reward:$('[data-ms="reward"]',r).value.trim(),info:$('[data-ms="info"]',r).value.trim()})).sort((a,b)=>a.level-b.level),v={...adv,id:$('#srId').value.trim(),name:$('#srName').value.trim(),category:$('#srCategory').value.trim(),origin:$('#srOrigin').value.trim(),secondaryOrigin:$('#srSecondary').value.trim(),theme:$('#srTheme').value.trim(),attribute:$('#srAttr').value.trim(),growth:$('#srGrowth').value.trim(),inheritLevel:Number($('#srInherit').value)||0,masterLevel:Number($('#srMaster').value)||0,notes:$('#srNotes').value,milestones:rows};if(!v.id)return toast('IDを入力してください');if(state.monsters.records.some((r,i)=>i!==x.index&&r.id===v.id))return toast('SOUL RECORD IDが重複しています');state.monsters.records[x.index]=v;selectedSoul=v.id;persist('SOUL RECORD「'+v.id+'」を保存');renderSoul();selectedSoul=v.id;setTimeout(()=>renderSoulDetail(),0)}

function stable(v){if(Array.isArray(v))return v.map(stable);if(v&&typeof v==='object')return Object.fromEntries(Object.keys(v).sort().filter(k=>k!=='raw').map(k=>[k,stable(v[k])]));return v}
function same(a,b){return JSON.stringify(stable(a))===JSON.stringify(stable(b))}
function compactFigure(f){return {masterId:f.masterId,displayOrder:f.displayOrder,name:f.name,rarity:f.rarity,image:f.image,canonicalTags:f.canonicalTags,notes:f.notes,story:{present:f.story?.present,sourceId:f.story?.sourceId,statsText:f.story?.statsText,traitText:f.story?.traitText,tags:f.story?.tags},piece:{present:f.piece?.present,sourceId:f.piece?.sourceId,mobPiece:f.piece?.mobPiece}}}
function compactTag(t){return {masterId:t.masterId,currentId:t.currentId,proposedId:t.proposedId,displayOrder:t.displayOrder,name:t.name,category:t.category,story:t.story,piece:t.piece,notes:t.notes}}
function compactEnemy(e){return {...e}}
function compactMonster(m){return {...m}}
function buildDiff(domain){let a=[],b=[],key=x=>x.masterId,label=x=>x.name||x.masterId,compact=x=>x;if(domain==='figures'){a=compareState.figures||[];b=state.figures||[];compact=compactFigure}else if(domain==='tags'){a=compareState.tags||[];b=state.tags||[];compact=compactTag}else if(domain==='story'){a=compareState.story?.enemies||[];b=state.story?.enemies||[];key=x=>x.id;label=x=>`${x.name||''} / ${x.id}`;compact=compactEnemy}else{a=compareState.monsters?.monsters||[];b=state.monsters?.monsters||[];key=x=>String(x.no);label=x=>`${x.name||''} / No.${x.no}`;compact=compactMonster}const am=new Map(a.map(x=>[key(x),x])),bm=new Map(b.map(x=>[key(x),x])),keys=new Set([...am.keys(),...bm.keys()]);return [...keys].map(k=>{const old=am.get(k),cur=bm.get(k),status=!old?'NEW':!cur?'REMOVED':same(compact(old),compact(cur))?'SAME':'CHANGED';return {key:k,label:label(cur||old),status,old,cur}}).sort((x,y)=>({CHANGED:0,NEW:1,REMOVED:2,SAME:3}[x.status]-{CHANGED:0,NEW:1,REMOVED:2,SAME:3}[y.status])||x.label.localeCompare(y.label,'ja'))}
function renderDiff(){const rows=buildDiff(diffDomain),counts=Object.fromEntries(['CHANGED','NEW','REMOVED','SAME'].map(k=>[k,rows.filter(x=>x.status===k).length]));$('#view').innerHTML=pageHead('DIFF','現在のMASTERと初期状態または別BACKUPを比較',`<button class="ghost" id="diffSeed">初期状態と比較</button><button class="primary" id="diffImport">比較BACKUP読込</button>`)+`<div class="notice good">比較元: <b>${esc(compareLabel)}</b>。比較するだけで現在データは変更しません。</div><div class="diff-summary grid"><div><b>${counts.CHANGED}</b><span>CHANGED</span></div><div><b>${counts.NEW}</b><span>NEW</span></div><div><b>${counts.REMOVED}</b><span>REMOVED</span></div><div><b>${counts.SAME}</b><span>SAME</span></div></div><div class="toolbar section"><select id="diffDomain"><option value="figures" ${diffDomain==='figures'?'selected':''}>FIGURES</option><option value="tags" ${diffDomain==='tags'?'selected':''}>TAGS</option><option value="story" ${diffDomain==='story'?'selected':''}>STORY ENEMIES</option><option value="monsters" ${diffDomain==='monsters'?'selected':''}>MOB MONSTERS</option></select><select id="diffStatus"><option value="changes">変更のみ</option><option value="all">すべて</option><option value="CHANGED">CHANGED</option><option value="NEW">NEW</option><option value="REMOVED">REMOVED</option></select><input id="diffSearch" class="search" placeholder="名前 / ID検索"></div><div id="diffRows" class="diff-list"></div>`;const refresh=()=>{const st=$('#diffStatus').value,q=$('#diffSearch').value.trim().toLowerCase();const rr=rows.filter(x=>(st==='all'||st==='changes'&&x.status!=='SAME'||x.status===st)&&(!q||(x.label+' '+x.key).toLowerCase().includes(q)));$('#diffRows').innerHTML=rr.length?rr.slice(0,600).map(x=>`<details class="diff-row ${x.status.toLowerCase()}"><summary><span class="diff-badge">${x.status}</span><b>${esc(x.label)}</b><small>${esc(String(x.key))}</small></summary><div class="compare-grid"><div><h4>BEFORE</h4><pre>${esc(JSON.stringify(x.old??null,null,2))}</pre></div><div><h4>CURRENT</h4><pre>${esc(JSON.stringify(x.cur??null,null,2))}</pre></div></div></details>`).join(''):'<div class="empty">該当する差分はありません</div>'};$('#diffDomain').onchange=()=>{diffDomain=$('#diffDomain').value;renderDiff()};$('#diffStatus').onchange=refresh;$('#diffSearch').oninput=refresh;$('#diffSeed').onclick=()=>{compareState=upgradeState(clone(SEED));compareLabel='初期スナップショット';renderDiff()};$('#diffImport').onclick=()=>$('#compareBackupFile').click();refresh()}


