function stripForRestore(x){const y=clone(x);if(y.sync)y.sync={imports:y.sync.imports||[],imageAudit:y.sync.imageAudit||null};return y}
function makeRestorePoint(label='手動復元ポイント'){try{localStorage.setItem(MANUAL_RESTORE_KEY,JSON.stringify(stripForRestore(state)));state.meta.lastRestorePoint={at:new Date().toISOString(),label};localStorage.setItem(STORAGE,JSON.stringify(state));toast('手動復元ポイントを保存しました')}catch(e){toast('復元ポイント保存に失敗: '+e.message)}}
function showRestorePoint(){let auto=null,manual=null;try{auto=JSON.parse(localStorage.getItem(RESTORE_KEY)||'null');manual=JSON.parse(localStorage.getItem(MANUAL_RESTORE_KEY)||'null')}catch(e){}const meta=state.meta.lastRestorePoint;const doRestore=(saved,label)=>{modal(`<h2>${label}へ復元しますか？</h2><div class="notice danger-note">現在の管理アプリ編集内容を保存状態へ戻します。ゲーム本体への影響はありません。</div><div class="modal-actions"><button class="ghost" id="rpc">キャンセル</button><button class="danger" id="rpd">復元する</button></div>`);$('#rpc').onclick=closeModal;$('#rpd').onclick=()=>{state=upgradeState(saved);localStorage.setItem(STORAGE,JSON.stringify(state));lastCommitted=clone(state);undoStack=[];dirty=true;closeModal();render();toast(label+'へ戻しました')}};modal(`<h2>RESTORE POINT</h2><div class="notice good">手動ポイントは固定保存、自動ポイントは編集のたびに直前状態へ更新されます。どちらもゲーム本体には触れません。</div><div class="section restore-grid"><div><b>MANUAL</b><p class="muted">${manual?(meta?esc(new Date(meta.at).toLocaleString('ja-JP')+' · '+meta.label):'利用可能'):'まだありません'}</p><button class="primary" id="rpSave">現在を手動保存</button> <button class="ghost" id="rpManual" ${manual?'':'disabled'}>MANUALへ戻す</button></div><div><b>AUTO</b><p class="muted">${auto?'直前編集状態を保存済み':'まだありません'}</p><button class="ghost" id="rpAuto" ${auto?'':'disabled'}>AUTOへ戻す</button></div></div><div class="modal-actions"><button class="ghost" id="rpClose">閉じる</button></div>`);$('#rpClose').onclick=closeModal;$('#rpSave').onclick=()=>{makeRestorePoint();closeModal()};if(manual)$('#rpManual').onclick=()=>doRestore(manual,'MANUAL');if(auto)$('#rpAuto').onclick=()=>doRestore(auto,'AUTO')}
function bytes(n){if(n<1024)return n+' B';if(n<1048576)return (n/1024).toFixed(1)+' KB';return (n/1048576).toFixed(1)+' MB'}
async function inflateRaw(u8){if(!('DecompressionStream'in window))throw new Error('このブラウザはZIP展開APIに未対応です');const ds=new DecompressionStream('deflate-raw');const ab=await new Response(new Blob([u8]).stream().pipeThrough(ds)).arrayBuffer();return new Uint8Array(ab)}
async function scanZipArchive(file){const ab=await file.arrayBuffer(),u8=new Uint8Array(ab),dv=new DataView(ab);let eocd=-1;for(let i=u8.length-22;i>=Math.max(0,u8.length-65557);i--){if(dv.getUint32(i,true)===0x06054b50){eocd=i;break}}if(eocd<0)throw new Error('ZIPの中央ディレクトリが見つかりません');const count=dv.getUint16(eocd+10,true),cdOff=dv.getUint32(eocd+16,true),dec=new TextDecoder('utf-8');let pos=cdOff,entries=[];for(let i=0;i<count&&pos+46<=u8.length;i++){if(dv.getUint32(pos,true)!==0x02014b50)break;const method=dv.getUint16(pos+10,true),csize=dv.getUint32(pos+20,true),usize=dv.getUint32(pos+24,true),nlen=dv.getUint16(pos+28,true),xlen=dv.getUint16(pos+30,true),clen=dv.getUint16(pos+32,true),loff=dv.getUint32(pos+42,true),name=dec.decode(u8.slice(pos+46,pos+46+nlen));entries.push({name,method,csize,usize,loff});pos+=46+nlen+xlen+clen}const low=entries.map(e=>e.name.toLowerCase()),projects=[];if(low.some(n=>n.includes('mob story')||n.includes('mob_story')||n.includes('/story/')))projects.push('MOB STORY');if(low.some(n=>n.includes('piece')||n.includes('figures_master')||n.includes('tags_master')))projects.push('MOB PIECE BATTLE');if(low.some(n=>n.includes('monsters')||n.includes('monster')&&n.includes('mob')))projects.push('MOB MONSTERS');const candidates=entries.filter(e=>e.usize<6_000_000&&/\.(json|js|html|txt)$/i.test(e.name)&&( /figures_master|tags_master|monster|soul|skill|figure|enemy|master-data|app\.js/i.test(e.name))).slice(0,80);let parsed={pieceFigures:null,pieceTags:null,masterBackup:null},signals={story:0,piece:0,monsters:0},candidateNames=[];for(const e of candidates){candidateNames.push(e.name);try{const lp=e.loff;if(dv.getUint32(lp,true)!==0x04034b50)continue;const nl=dv.getUint16(lp+26,true),xl=dv.getUint16(lp+28,true),start=lp+30+nl+xl;let data=u8.slice(start,start+e.csize);if(e.method===8)data=await inflateRaw(data);else if(e.method!==0)continue;const txt=dec.decode(data),ln=e.name.toLowerCase();if(/mob story|enemyprofiles|magiccatalog|story/i.test(txt))signals.story++;if(/figures_master|tags_master|mobpiece|piece battle/i.test(txt)||ln.includes('figures_master')||ln.includes('tags_master'))signals.piece++;if(/soul record|fixedfusions|rankorder|recordtype|mob monsters/i.test(txt))signals.monsters++;if(/figures_master.*\.json$/i.test(e.name)){const o=JSON.parse(txt);parsed.pieceFigures=Array.isArray(o)?o.length:Array.isArray(o.figures)?o.figures.length:Object.keys(o||{}).length}if(/tags_master.*\.json$/i.test(e.name)){const o=JSON.parse(txt);parsed.pieceTags=Array.isArray(o)?o.length:Array.isArray(o.tags)?o.tags.length:Object.keys(o||{}).length}if(/mob-master-backup.*\.json$/i.test(e.name)){const o=JSON.parse(txt);if(o.figures&&o.tags&&o.story&&o.monsters)parsed.masterBackup=o}}catch(err){}}
 if(!projects.length){if(signals.story)projects.push('MOB STORY');if(signals.piece)projects.push('MOB PIECE BATTLE');if(signals.monsters)projects.push('MOB MONSTERS')}return {id:'scan_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,6),fileName:file.name,size:file.size,modified:file.lastModified||0,scannedAt:new Date().toISOString(),files:entries.length,projects:[...new Set(projects)],signals,known:{pieceFigures:parsed.pieceFigures,pieceTags:parsed.pieceTags},candidateNames:candidateNames.slice(0,30),embeddedMaster:!!parsed.masterBackup,_embeddedMaster:parsed.masterBackup||null}}
async function handleZipImports(files){if(!files.length)return;makeRestorePoint('ZIP読込前');let ok=0;for(const f of files){try{toast('ZIP解析中: '+f.name);const m=await scanZipArchive(f);const clean={...m};delete clean._embeddedMaster;state.sync.imports.unshift(clean);state.sync.imports=state.sync.imports.slice(0,12);if(m._embeddedMaster){compareState=upgradeState(m._embeddedMaster);compareLabel=f.name+' 内 MASTER BACKUP'}ok++}catch(e){state.sync.imports.unshift({id:'fail_'+Date.now().toString(36),fileName:f.name,size:f.size,scannedAt:new Date().toISOString(),error:e.message,projects:[],files:0})}}persist(`ZIPスキャン ${ok}/${files.length}件完了`,{noUndo:true});view='sync';render()}
