function renderSync(){const s=summary(),story=importProjectStatus('MOB STORY'),piece=importProjectStatus('MOB PIECE BATTLE'),mon=importProjectStatus('MOB MONSTERS'),dups=imagePathDuplicates(),ia=state.sync.imageAudit;const card=(name,imp,body)=>`<div class="sync-card"><div class="sync-card-head"><div><small>SOURCE</small><h3>${name}</h3></div><span class="${imp?'pill good':'pill'}">${imp?'SCANNED':'NOT SCANNED'}</span></div>${body}<div class="source-meta">${imp?`${esc(imp.fileName)} · ${imp.files} files · ${new Date(imp.scannedAt).toLocaleString('ja-JP')}`:'ZIPを読み込むまでMASTERの現スナップショットだけを表示'}</div></div>`;$('#view').innerHTML=pageHead('SYNC CENTER','最新版ZIPを安全にスキャンし、3作品とMASTERの状態を確認',`<button class="primary" id="syncZip">＋ ZIPをスキャン</button>`)+`<div class="notice good"><b>SCAN ONLY:</b> ZIPを読み込んでもMASTERやゲーム本体は自動変更しません。ファイル構造と認識できるデータだけを調査します。</div><div class="sync-cards">${card('MOB STORY',story,`<div class="sync-kpis"><b>${s.sf}</b><span>MASTER FIGURES</span><b>${s.se}</b><span>STORY ENCOUNTERS</span></div>`)}${card('MOB PIECE BATTLE',piece,`<div class="sync-kpis"><b>${s.pf}</b><span>MASTER FIGURES</span><b>${piece?.known?.pieceFigures??'—'}</b><span>ZIP FIGURES</span></div>`)}${card('MOB MONSTERS',mon,`<div class="sync-kpis"><b>${s.mm}</b><span>MONSTERS</span><b>${state.monsters.records.length}</b><span>SOUL RECORDS</span></div>`)}</div><div class="sync-tools grid"><section class="card"><h2>IMAGE AUDIT</h2><p class="muted">GitHub Raw URLを使って画像404を検査。ローカル重複パスは通信なしで検出します。</p><div class="issue-list"><div class="issue">重複画像パス：<b>${dups.length}</b></div><div class="issue">最新監査：<b>${ia?`${ia.ok}/${ia.total} OK · missing ${ia.missing}`:'未実行'}</b></div></div><button class="primary" id="runImageAudit">GitHub画像を監査</button> <button class="ghost" id="imageReport">画像台帳JSON</button><div id="imageAuditProgress" class="muted"></div></section><section class="card"><h2>SAFE WORKFLOW</h2><ol class="steps"><li>最新版ZIPをここでスキャン</li><li>DIFF / ORGANIZEで整理</li><li>CHECKでERROR 0を確認</li><li>REFLECTで反映予定を確認</li><li>JSONを書き出してゲーム側へ手動反映</li></ol></section></div><section class="card"><div class="section-title"><h2>ZIP SCAN HISTORY</h2><button class="ghost" id="clearScans">履歴消去</button></div><div class="scan-list">${(state.sync.imports||[]).map(x=>`<details class="scan-row ${x.error?'bad':''}"><summary><b>${esc(x.fileName)}</b><span>${esc((x.projects||[]).join(' / ')||'UNKNOWN')}</span><small>${bytes(x.size||0)}</small></summary>${x.error?`<div class="notice danger-note">${esc(x.error)}</div>`:`<div class="scan-detail"><div>Files <b>${x.files}</b></div><div>STORY signal <b>${x.signals?.story||0}</b></div><div>PIECE signal <b>${x.signals?.piece||0}</b></div><div>MONSTERS signal <b>${x.signals?.monsters||0}</b></div><div>PIECE figures <b>${x.known?.pieceFigures??'—'}</b></div><div>PIECE tags <b>${x.known?.pieceTags??'—'}</b></div></div><div class="candidate-files">${(x.candidateNames||[]).map(n=>`<code>${esc(n)}</code>`).join('')}</div>`}</details>`).join('')||'<div class="empty">まだZIPをスキャンしていません</div>'}</div></section>`;$('#syncZip').onclick=()=>$('#zipImportFiles').click();$('#clearScans').onclick=()=>{state.sync.imports=[];persist('ZIPスキャン履歴を消去');renderSync()};$('#runImageAudit').onclick=runImageAudit;$('#imageReport').onclick=()=>download('mob-image-audit.json',buildImageLedger())}
function imagePathDuplicates(){const m=new Map();state.figures.forEach(f=>{const p=(f.image?.path||'').trim();if(p)m.set(p,(m.get(p)||[]).concat(f.name||f.masterId))});return [...m].filter(([,v])=>v.length>1)}
function buildImageLedger(){const folders={};state.figures.forEach(f=>{const p=f.image?.path||'',folder=f.image?.folder||p.split('/').slice(0,-1).join('/')||'(root)';folders[folder]=folders[folder]||[];folders[folder].push({masterId:f.masterId,name:f.name,file:f.image?.file||'',path:p})});const nextNumbers={};for(const [folder,rows] of Object.entries(folders)){const nums=rows.map(r=>parseInt(String(r.file).match(/\d+/)?.[0]||'',10)).filter(Number.isFinite);nextNumbers[folder]=nums.length?Math.max(...nums)+1:1}return {generatedAt:new Date().toISOString(),total:state.figures.length,duplicates:imagePathDuplicates().map(([path,names])=>({path,names})),nextNumbers,folders,imageAudit:state.sync.imageAudit||null}}
